UPDATE public.questions
SET explanation_data = explanation_data || '{"think": "外れ値がこわいのは、平均や分散のような「全員の値を使う計算」を、たった1件で大きく狂わせるから。1650cmが1件混ざるだけで、クラスの平均身長は何十cmも跳ね上がる。だから分析の前にヒストグラムのようなグラフで外れ値を探し、ミスなら直し、本物なら「入れた場合と外した場合」の両方を確かめるのが定石。"}'::jsonb
WHERE source_ref = 'stats1-q06'
  AND subject_id = (SELECT id FROM public.subjects WHERE slug = 'stats-basics');

UPDATE public.questions
SET explanation_data = explanation_data || '{"viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><rect x=\"24\" y=\"103.8\" width=\"10\" height=\"4.199999999999999\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"36\" y=\"101.0\" width=\"10\" height=\"7.0\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"48\" y=\"96.8\" width=\"10\" height=\"11.2\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"60\" y=\"89.8\" width=\"10\" height=\"18.2\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"72\" y=\"80.0\" width=\"10\" height=\"28.0\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"84\" y=\"66.0\" width=\"10\" height=\"42.0\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"96\" y=\"46.400000000000006\" width=\"10\" height=\"61.599999999999994\" fill=\"#c9a04a\" opacity=\"0.6\"/><rect x=\"108\" y=\"24.0\" width=\"10\" height=\"84.0\" fill=\"#c9a04a\" opacity=\"0.6\"/><line x1=\"20\" y1=\"108\" x2=\"140\" y2=\"108\" stroke=\"#2a2f3f\"/><text x=\"80\" y=\"132\" fill=\"#8892a4\" font-size=\"9.5\" text-anchor=\"middle\">元はいびつな形</text><line x1=\"152\" y1=\"70\" x2=\"200\" y2=\"70\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><polygon points=\"200,70 191,65 191,75\" fill=\"#8892a4\"/><text x=\"176\" y=\"60\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">平均を</text><text x=\"176\" y=\"92\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">何度もとる</text><path d=\"M212 108 C 236 108, 244 30, 266 30 C 288 30, 296 108, 320 108\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.6\"/><line x1=\"212\" y1=\"108\" x2=\"320\" y2=\"108\" stroke=\"#2a2f3f\"/><text x=\"266\" y=\"132\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">「平均」の分布はベル型</text></svg>", "vs": "大数の法則は「回数を増やすと1つの割合や平均が理論値そのものに近づく」という話。中心極限定理は「1回に平均を取る標本の大きさ n が十分大きければ、その平均の分布が正規分布に近づく」という話で、注目している対象が違う。何度も平均を計算してヒストグラムで確かめているのは、あくまで形を目で見えるようにするためのシミュレーションにすぎない。分布の形を正規分布に近づけている本当の要因は、標本を取り直した回数ではなく、1回あたりの標本の大きさ（n）そのものである。"}'::jsonb
WHERE source_ref = 'stats2-q10'
  AND subject_id = (SELECT id FROM public.subjects WHERE slug = 'stats-basics');

UPDATE public.questions
SET explanation_data = explanation_data || '{"think": "標本を増やすほどばらつきが縮む理由は、すくう量が多いほど、濃い部分・薄い部分をたまたま拾う運の影響が打ち消し合って（ならされて）、鍋全体の本当の味に近づくから。これを数式で表したのが標準誤差で、母集団の標準偏差を標本の大きさ（n）の平方根で割った値として計算される。割る数である√nが大きくなるほど、割り算の答えである標準誤差は小さくなる。ひとさじ（小さいn）よりお玉10杯ぶん（大きいn）のほうがnが大きいので、√nも大きくなり、標準誤差は小さくなる。だから標本が大きいほど、標本平均は真の値のまわりに小さくばらつくようになる。"}'::jsonb
WHERE source_ref = 'stats3-q06'
  AND subject_id = (SELECT id FROM public.subjects WHERE slug = 'stats-basics');

UPDATE public.questions
SET explanation_data = explanation_data || '{"think": "誤差が縮む理由は、人数が増えるほどたまたまの偏り（運）が打ち消し合って（ならされて）、全体の平均が真の値に近づいていくから。ただしこの「ならされ方」は人数にそのまま比例するのではなく、人数の平方根（√n）に比例して効いてくる。標準誤差は、母集団の標準偏差を標本の大きさ（n）の平方根（√n）で割って計算される。√nを2倍にするには、nそのものは2×2で4倍にしないといけない（√400=20は√100=10のちょうど2倍）。標準誤差は√nで割った値なので、√nが2倍になれば標準誤差は半分になる。つまり誤差を半分にしたいなら、100人の4倍である400人くらいが必要になる。"}'::jsonb
WHERE source_ref = 'stats3-q10'
  AND subject_id = (SELECT id FROM public.subjects WHERE slug = 'stats-basics');

COMMIT;
